/* @lc app=leetcode id=2234 lang=kotlin */
class Solution { fun maximumBeauty(flowers: IntArray, newFlowers: Long, target: Int, full: Int, partial: Int): Long = flowers.map { it.coerceAtMost(target).toLong() }.sorted().let { f -> LongArray(f.size + 1).apply { f.forEachIndexed { i, v -> this[i + 1] = this[i] + v } }.let { pref -> (0..f.size).fold(0L) { maxB, c -> (newFlowers - (c.toLong() * target - (pref[f.size] - pref[f.size - c]))).let { rem -> if (rem < 0) maxB else (f.size - c).let { n -> if (n == 0) maxOf(maxB, c.toLong() * full) else DeepRecursiveFunction<LongArray, Long> { (low, high, bestP) -> if (low > high) bestP else (low + (high - low) / 2).let { mid -> (0 until n).let { i -> java.util.Arrays.binarySearch(f.toLongArray(), 0, n, mid).let { pos -> (if (pos < 0) -pos - 2 else pos).let { idx -> (idx + 1).toLong() * mid - pref[idx + 1] } } } }.let { needed -> if (needed <= rem) callRecursive(longArrayOf(mid + 1, high, mid)) else callRecursive(longArrayOf(low, mid - 1, bestP)) } } }.invoke(longArrayOf(f[0], target.toLong() - 1, f[0])).let { bestP -> maxOf(maxB, c.toLong() * full + bestP * partial) } } } } } }